"use strict";(self.webpackChunkruststream_website=self.webpackChunkruststream_website||[]).push([["4991"],{6058(e,t,s){s.r(t),s.d(t,{metadata:()=>r,default:()=>c,frontMatter:()=>a,contentTitle:()=>i,toc:()=>l,assets:()=>h});var r=JSON.parse('{"id":"guides/http","title":"HTTP frameworks","description":"RustStream is not an HTTP framework and does not try to become one. When a service exposes a","source":"@site/../archive/docs/guides/http.md","sourceDirName":"guides","slug":"/guides/http","permalink":"/ruststream/0.5/guides/http","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"docs","previous":{"title":"Failure policy","permalink":"/ruststream/0.5/guides/failure-policy"},"next":{"title":"Logging","permalink":"/ruststream/0.5/guides/logging"}}'),n=s(4848),o=s(8453);let a={},i="HTTP frameworks",h={},l=[{value:"Running beside an HTTP server",id:"running-beside-an-http-server",level:2},{value:"Publishing straight from a request",id:"publishing-straight-from-a-request",level:2},{value:"Transactional outbox",id:"transactional-outbox",level:2},{value:"Try it",id:"try-it",level:2}];function d(e){let t={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"http-frameworks",children:"HTTP frameworks"})}),"\n",(0,n.jsx)(t.p,{children:"RustStream is not an HTTP framework and does not try to become one. When a service exposes a\nsynchronous HTTP API and consumes messages, the HTTP framework (axum, actix-web, or any other\ntokio-based stack) runs beside the RustStream app in the same process and runtime. This page shows\nthe wiring on axum and the pattern that makes the combination reliable: a transactional outbox."}),"\n",(0,n.jsxs)(t.p,{children:["The full compiled example lives at\n",(0,n.jsx)(t.a,{href:"https://github.com/powersemmi/ruststream/blob/main/examples/http_outbox.rs",children:(0,n.jsx)(t.code,{children:"examples/http_outbox.rs"})}),":"]}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-text",children:"cargo run --example http_outbox --features macros,memory,json\n"})}),"\n",(0,n.jsx)(t.h2,{id:"running-beside-an-http-server",children:"Running beside an HTTP server"}),"\n",(0,n.jsxs)(t.p,{children:["Both sides come up in ",(0,n.jsx)(t.code,{children:"main"}),". ",(0,n.jsx)(t.code,{children:"start()"})," brings the messaging side up in the background - the\nstate producer, broker connects, subscription opens - and resolves once the service is running,\nso a startup failure surfaces before the HTTP side accepts traffic. The returned ",(0,n.jsx)(t.code,{children:"RunningApp"}),"\nhandle coordinates the two lifetimes: ",(0,n.jsx)(t.code,{children:"stopping()"})," is an owned future that resolves if the\nmessaging side tears itself down (a fail-fast failure), which plugs straight into axum's\n",(0,n.jsx)(t.code,{children:"with_graceful_shutdown"})," so the process does not keep serving HTTP with a dead consumer; and\n",(0,n.jsx)(t.code,{children:"shutdown()"})," is the explicit graceful teardown - the ",(0,n.jsx)(t.code,{children:"on_shutdown"})," hooks, a drain of in-flight\nhandlers bounded by the ",(0,n.jsx)(t.a,{href:"/ruststream/0.5/guides/lifespan#shutdown-timeout",children:"shutdown timeout"}),", broker shutdown - once\nthe HTTP server has stopped. A publisher is taken from the broker before the app consumes it; it\nis a plain value, safe to clone into whatever state the HTTP framework carries:"]}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:'let broker = MemoryBroker::new();\n// Taken from the broker before the app consumes it; resolves its connection on first use.\nlet egress = broker.publisher();\nlet app =\n    RustStream::new(AppInfo::new("orders", "0.1.0")).with_broker(broker, |b| b.include(fulfil));\n\n// The messaging side starts in the background; a startup failure (a broker refusing to\n// connect, a subscription failing to open) surfaces here, before HTTP accepts traffic.\nlet running = app.start().await?;\n\nlet store = Arc::new(Mutex::new(Store::default()));\ntokio::spawn(relay_outbox(store.clone(), egress));\n\nlet router = Router::new()\n    .route("/orders", post(place_order))\n    .with_state(store);\n\nlet listener = tokio::net::TcpListener::bind("127.0.0.1:8080").await?;\nprintln!("orders API on http://127.0.0.1:8080/orders");\n// The host owns the signals. HTTP stops on Ctrl+C, or when the messaging side tears itself\n// down (fail-fast) so the process does not keep serving with a dead consumer; either way the\n// messaging side then drains gracefully.\nlet stopping = running.stopping();\naxum::serve(listener, router)\n    .with_graceful_shutdown(async move {\n        tokio::select! {\n            _ = tokio::signal::ctrl_c() => {}\n            () = stopping => {}\n        }\n    })\n    .await?;\nrunning.shutdown().await?;\n'})}),"\n",(0,n.jsx)(t.p,{children:"The subscriber side is an ordinary handler; the same service consumes what its HTTP endpoints\nproduce, and any other service subscribed to the broker sees the events too:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:'/// The same service consumes what its HTTP endpoints produce; any other service subscribed to\n/// the broker would see the event too.\n#[subscriber("orders.placed")]\nasync fn fulfil(order: &OrderPlaced) -> HandlerResult {\n    println!("fulfilling order {} ({})", order.id, order.item);\n    HandlerResult::Ack\n}\n'})}),"\n",(0,n.jsx)(t.h2,{id:"publishing-straight-from-a-request",children:"Publishing straight from a request"}),"\n",(0,n.jsxs)(t.p,{children:["The simplest integration puts the publisher into the HTTP framework's state and publishes on the\nrequest path, exactly like ",(0,n.jsx)(t.a,{href:"/ruststream/0.5/guides/publishing",children:"publishing from inside a handler"}),": encode with the\ncodec, build an ",(0,n.jsx)(t.code,{children:"OutgoingMessage"}),", and await the publish. The\n",(0,n.jsx)(t.a,{href:"/ruststream/0.5/guides/metrics",children:"metrics guide's complete server"})," does this to drive its counters."]}),"\n",(0,n.jsx)(t.p,{children:"The trade-off is coupling: a broker outage now fails or stalls HTTP requests, and a crash after\nthe database write but before the publish loses the event (or publishes an event for a write that\nrolled back, in the opposite order). If the endpoint also writes to a database, that gap is a\nconsistency bug waiting for a deploy window. The fix is the transactional outbox."}),"\n",(0,n.jsx)(t.h2,{id:"transactional-outbox",children:"Transactional outbox"}),"\n",(0,n.jsx)(t.p,{children:"Instead of publishing on the request path, the endpoint records the event next to the business\nwrite, atomically. A relay then moves recorded events to the broker:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:"/// The integration event the HTTP side hands to the messaging side.\n#[derive(Debug, Clone, Serialize, Deserialize)]\nstruct OrderPlaced {\n    id: u64,\n    item: String,\n}\n"})}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:"/// The business records and the pending outbox rows, committed together. With a real database\n/// both inserts run in one SQL transaction; the mutex over the pair plays that role here, so an\n/// order is never stored without its event, and no event exists without its order.\n#[derive(Default)]\nstruct Store {\n    orders: Vec<OrderPlaced>,\n    outbox: VecDeque<OrderPlaced>,\n}\n"})}),"\n",(0,n.jsx)(t.p,{children:"The endpoint only writes to the store. Recording the order and queueing its event is one atomic\nstep, and no broker I/O can fail or stall the HTTP response:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:'/// The request path only writes to the store: recording the order and queueing its event is one\n/// atomic step, and no broker I/O can fail or stall the HTTP response.\nasync fn place_order(\n    State(store): State<Arc<Mutex<Store>>>,\n    Json(order): Json<OrderPlaced>,\n) -> &\'static str {\n    let mut store = store.lock().await;\n    store.orders.push(order.clone());\n    store.outbox.push_back(order);\n    "accepted\\n"\n}\n'})}),"\n",(0,n.jsx)(t.p,{children:"A background task drains the outbox into the broker. A row is removed only after its publish\nsucceeds, so a broker outage delays events instead of losing them; a crash between the publish and\nthe removal re-publishes the row on restart. Consumers therefore see at-least-once delivery, the\nusual contract of an outbox, and handle duplicates the same way they handle redeliveries from the\nbroker itself:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream/blob/docs/archive/v0.5/examples/http_outbox.rs"',children:'/// Drains the outbox into the broker. A row is removed only after its publish succeeds, so a\n/// broker outage delays events instead of losing them; a crash between publish and removal\n/// re-publishes the row on restart, which is the usual at-least-once contract of an outbox.\nasync fn relay_outbox(store: Arc<Mutex<Store>>, egress: MemoryPublisher) {\n    let mut tick = tokio::time::interval(Duration::from_millis(200));\n    loop {\n        tick.tick().await;\n        loop {\n            let Some(event) = store.lock().await.outbox.front().cloned() else {\n                break;\n            };\n            let payload = JsonCodec.encode(&event).expect("serializable");\n            let out = OutgoingMessage::new("orders.placed", payload.as_ref());\n            if egress.publish(out).await.is_err() {\n                // Keep the row and retry on the next tick.\n                break;\n            }\n            store.lock().await.outbox.pop_front();\n        }\n    }\n}\n'})}),"\n",(0,n.jsxs)(t.p,{children:["With a real database the ",(0,n.jsx)(t.code,{children:"Store"})," is a table plus an ",(0,n.jsx)(t.code,{children:"outbox"})," table written in one SQL\ntransaction, and the relay reads ",(0,n.jsx)(t.code,{children:"outbox"})," rows in insertion order, publishes, and deletes them.\nEverything else stays as shown: the broker, the publisher, and the subscriber do not know the\noutbox exists."]}),"\n",(0,n.jsx)(t.h2,{id:"try-it",children:"Try it"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-text",children:'curl -X POST http://127.0.0.1:8080/orders \\\n  -H \'content-type: application/json\' -d \'{"id":1,"item":"book"}\'\n'})}),"\n",(0,n.jsxs)(t.p,{children:["The response returns as soon as the store commits; the ",(0,n.jsx)(t.code,{children:"fulfil"})," handler logs the order a moment\nlater, when the relay has published the event."]})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);